installer-gui-script.script:
function pb_is_apple_silicon() {
    var arm64 = null;
    var machine = null;
    try { arm64 = system.sysctl('hw.optional.arm64'); } catch (e) { arm64 = null; }
    try { machine = system.sysctl('hw.machine'); } catch (e) { machine = null; }
    return arm64 == 1 || machine == 'arm64';
}

function pb_installation_check() {
    if (!pb_is_apple_silicon()) {
        my.result.type = 'Fatal';
        my.result.title = 'Mac Apple Silicon requis';
        my.result.message = 'Parabellum ne fonctionne que sur les Mac Apple Silicon (puce M1 ou plus récente). ' +
            'Ce Mac utilise un processeur Intel : l\'installation est annulée.';
        return false;
    }
    return true;
}
